from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn

text_paras = [
"Рославль - один из древнейших городов Смоленской земли. Он расположен на юге Смоленской области, на левом берегу реки Остер, и издавна занимал важное положение на путях между Смоленском, Брянском, Орлом и белорусскими землями. Официальной датой основания города считается 1137 год. Его возникновение связывают со смоленским князем Ростиславом Мстиславичем. Первоначально город назывался Ростиславлем - по имени основателя. Древний центр находился на возвышенном месте, которое сегодня известно как Бурцева гора. Здесь располагался укрепленный детинец, окруженный валом. Археологические находки XII-XIII веков подтверждают, что поселение уже в ранний период было заметным административным и военным пунктом. В письменных источниках Рославль впервые упоминается в начале XIII века, в грамоте, связанной со Смоленской землей.",
"В средние века судьба Рославля была тесно связана с борьбой за Смоленское княжество. После усиления Великого княжества Литовского город в конце XIV - начале XV века оказался под его властью. В 1395 году великий князь литовский Витовт захватил Смоленск, а после окончательной утраты Смоленским княжеством независимости в 1404 году Рославль вошел в состав Великого княжества Литовского. Пограничное положение делало его участником русско-литовских войн. В 1515 году город был занят русскими войсками, а по условиям перемирия 1522 года остался в составе Русского государства. В начале XVII века, во время Смуты и войн с Речью Посполитой, власть над Рославлем вновь менялась. В 1611 году его заняли польско-литовские войска, а Деулинское перемирие 1618 года закрепило город за Речью Посполитой. Окончательно в состав Русского государства Рославль вернулся в ходе русско-польской войны 1654-1667 годов. Андрусовское перемирие 1667 года юридически подтвердило эту принадлежность.",
"Начало XVIII века связано с Северной войной. В октябре 1708 года в Рославле находился штаб Петра I. После административных преобразований город стал уездным центром Смоленской губернии, хотя на некоторое время входил в состав Рижской губернии. В конце XVIII века началась регулярная перепланировка городского центра. План 1780 года, позднее скорректированный, определил сетку улиц и основные направления застройки. В Рославле возводились каменные административные здания, торговые дома, храмы и усадьбы. К историческим памятникам относятся сооружения Спасо-Преображенского монастыря, Вознесенская церковь, церковь Казанской иконы Божией Матери, церковь Рождества Богородицы, здания бывшей городской думы и дворянского собрания. Эти постройки во многом сформировали облик центральной части города.",
"Во время Отечественной войны 1812 года Рославль оказался в полосе военных действий. В городе создавались конные отряды для борьбы с французскими мародерами, а в сентябре французский отряд на несколько часов занял Рославль. После войны город продолжил развиваться как торговый и ремесленный центр. Особенно заметные изменения произошли во второй половине XIX века. В 1855 году через Рославль прошло шоссе, связавшее Витебск, Смоленск и Орел. В 1868 году открылось железнодорожное движение по линиям Витебск - Рославль и Рославль - Орел. Город превратился в крупный железнодорожный узел. При станции появились мастерские, которые со временем стали одним из важнейших промышленных предприятий. Железная дорога ускорила торговлю, рост населения и развитие городской инфраструктуры. С Рославльскими железнодорожными мастерскими связан и важный эпизод истории техники: в 1883 году здесь применялась электродуговая сварка, а в 1892 году отремонтированный с ее помощью бронзовый колокол демонстрировался на Всероссийской электрической выставке.",
"После революционных событий 1917 года в Рославле была установлена советская власть. В 1929 году он стал районным центром Западной области, а после образования Смоленской области в 1937 году вошел в ее состав. Железнодорожная сеть продолжала расширяться: в 1931 году открылось движение по линии Рославль - Могилев, в 1935 году - по линии Рославль - Сухиничи. Самым тяжелым периодом в истории города стала Великая Отечественная война. 3 августа 1941 года Рославль был оккупирован немецкими войсками. На территории города действовали лагерь для военнопленных, тюрьма и еврейское гетто. По данным Большой российской энциклопедии, в местах заключения и массового уничтожения погибли десятки тысяч людей, а сам город был почти полностью разрушен. Рославль освободили 25 сентября 1943 года в ходе Смоленско-Рославльской наступательной операции. Послевоенные годы стали временем масштабного восстановления жилых кварталов, предприятий, дорог и коммунальной инфраструктуры.",
"Во второй половине XX века Рославль вновь укрепил значение промышленного и транспортного центра юга Смоленской области. В городе развивались машиностроение, ремонт железнодорожного транспорта и другие отрасли. Одновременно велась работа по сохранению исторического наследия. В 1970 году Рославль был включен в число исторических городов. Значительную роль в изучении прошлого играет Рославльский историко-художественный музей, история которого начинается в 1920 году. В фондах сохраняются археологические находки, документы и предметы городского быта. Особое место занимает Бурцева гора - территория древнего детинца, напоминающая о первоначальном Рославле XII века. Современный город сохраняет черты разных эпох: регулярную планировку конца XVIII века, храмы и гражданские здания XIX столетия, советскую и современную застройку. История Рославля показывает, насколько сильно на развитие города влияли его географическое положение и пограничный характер Смоленской земли. За несколько столетий город переживал войны, переходы из одного государства в другое, разрушения и восстановление, но сохранял значение местного административного, торгового и транспортного центра."
]

doc = Document()
